"use client";

import { cn } from "../lib/cn";
import type { DataTableLook } from "../lib/looks";
import { Checkbox } from "../atoms/checkbox";
import { EmptyState } from "./empty-state";
import {
  useCallback,
  useMemo,
  useState,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
  type ThHTMLAttributes,
  type TdHTMLAttributes,
} from "react";

export type { DataTableLook };

export type DataTableDensity = "comfortable" | "compact";

export type DataTableSortDirection = "asc" | "desc";

export type DataTableSortState = {
  columnId: string;
  direction: DataTableSortDirection;
} | null;

export type DataTableSelectionMode = "none" | "single" | "multiple";

export type DataTableColumnAlign = "start" | "center" | "end";

export type DataTableColumn<T> = {
  id: string;
  header: ReactNode;
  /** Simple field key — used for cell text and default sort. */
  accessor?: keyof T & string;
  cell?: (row: T, index: number) => ReactNode;
  sortable?: boolean;
  /** Custom sort key (preferred over raw accessor when sorting). */
  sortValue?: (row: T) => string | number | boolean | null | undefined;
  align?: DataTableColumnAlign;
  width?: string | number;
};

export type DataTableProps<T> = Omit<
  HTMLAttributes<HTMLDivElement>,
  "children"
> & {
  data: T[];
  columns: DataTableColumn<T>[];
  getRowId?: (row: T, index: number) => string;
  /** soft | solid | glass | outline | ghost */
  look?: DataTableLook;
  density?: DataTableDensity;
  /** Sticky thead. Default true. */
  stickyHeader?: boolean;
  loading?: boolean;
  /** Full empty override (replaces default EmptyState). */
  empty?: ReactNode;
  emptyTitle?: ReactNode;
  emptyDescription?: ReactNode;
  selectionMode?: DataTableSelectionMode;
  selectedIds?: string[];
  defaultSelectedIds?: string[];
  onSelectionChange?: (ids: string[]) => void;
  sort?: DataTableSortState;
  defaultSort?: DataTableSortState;
  onSortChange?: (sort: DataTableSortState) => void;
  /**
   * When true (default), reorder `data` client-side for active sort.
   * Set false for server-ordered rows (still shows sort UI if controlled).
   */
  clientSort?: boolean;
  /** Skeleton row count while loading. Default 5. */
  loadingRowCount?: number;
  "aria-label"?: string;
};

/* —— Low-level table compounds —— */

export type TableProps = HTMLAttributes<HTMLTableElement>;
export function Table({ className, ...props }: TableProps) {
  return <table className={cn("sg-table", className)} {...props} />;
}

export type TableHeaderProps = HTMLAttributes<HTMLTableSectionElement>;
export function TableHeader({ className, ...props }: TableHeaderProps) {
  return <thead className={cn("sg-table-header", className)} {...props} />;
}

export type TableBodyProps = HTMLAttributes<HTMLTableSectionElement>;
export function TableBody({ className, ...props }: TableBodyProps) {
  return <tbody className={cn("sg-table-body", className)} {...props} />;
}

export type TableRowProps = HTMLAttributes<HTMLTableRowElement> & {
  selected?: boolean;
};
export function TableRow({
  className,
  selected,
  ...props
}: TableRowProps) {
  return (
    <tr
      className={cn("sg-table-row", className)}
      data-selected={selected || undefined}
      {...props}
    />
  );
}

export type TableHeadProps = Omit<
  ThHTMLAttributes<HTMLTableCellElement>,
  "align"
> & {
  align?: DataTableColumnAlign;
  sortable?: boolean;
  sorted?: DataTableSortDirection | false;
};
export function TableHead({
  className,
  align = "start",
  sortable,
  sorted,
  children,
  ...props
}: TableHeadProps) {
  const ariaSort =
    sorted === "asc"
      ? "ascending"
      : sorted === "desc"
        ? "descending"
        : sortable
          ? "none"
          : undefined;

  return (
    <th
      className={cn("sg-table-head", className)}
      data-align={align === "start" ? undefined : align}
      data-sortable={sortable || undefined}
      data-sorted={sorted || undefined}
      aria-sort={ariaSort}
      {...props}
    >
      {children}
    </th>
  );
}

export type TableCellProps = Omit<
  TdHTMLAttributes<HTMLTableCellElement>,
  "align"
> & {
  align?: DataTableColumnAlign;
};
export function TableCell({
  className,
  align = "start",
  ...props
}: TableCellProps) {
  return (
    <td
      className={cn("sg-table-cell", className)}
      data-align={align === "start" ? undefined : align}
      {...props}
    />
  );
}

/* —— Helpers —— */

function defaultRowId<T>(row: T, index: number): string {
  if (row && typeof row === "object") {
    const rec = row as Record<string, unknown>;
    if (typeof rec.id === "string" || typeof rec.id === "number") {
      return String(rec.id);
    }
  }
  return String(index);
}

function compareSortValues(
  a: string | number | boolean | null | undefined,
  b: string | number | boolean | null | undefined,
): number {
  if (a == null && b == null) return 0;
  if (a == null) return 1;
  if (b == null) return -1;
  if (typeof a === "number" && typeof b === "number") return a - b;
  if (typeof a === "boolean" && typeof b === "boolean") {
    return Number(a) - Number(b);
  }
  return String(a).localeCompare(String(b), undefined, {
    numeric: true,
    sensitivity: "base",
  });
}

function cellContent<T>(
  column: DataTableColumn<T>,
  row: T,
  index: number,
): ReactNode {
  if (column.cell) return column.cell(row, index);
  if (column.accessor) {
    const value = (row as Record<string, unknown>)[column.accessor];
    if (value == null) return null;
    if (
      typeof value === "string" ||
      typeof value === "number" ||
      typeof value === "boolean"
    ) {
      return String(value);
    }
    return null;
  }
  return null;
}

function columnWidthStyle(width?: string | number): CSSProperties | undefined {
  if (width == null) return undefined;
  return { width: typeof width === "number" ? `${width}px` : width };
}

function SortGlyph({ direction }: { direction?: DataTableSortDirection | false }) {
  if (direction === "asc") {
    return (
      <span className="sg-table-sort-icon" aria-hidden="true">
        ↑
      </span>
    );
  }
  if (direction === "desc") {
    return (
      <span className="sg-table-sort-icon" aria-hidden="true">
        ↓
      </span>
    );
  }
  return (
    <span className="sg-table-sort-icon sg-table-sort-icon-idle" aria-hidden="true">
      ↕
    </span>
  );
}

/**
 * Molecule — DataTable
 * Product-list table: sort, selection, sticky header, density, look, empty/loading.
 * Virtualization ships in 1.7b (`virtualized` API TBD).
 */
export function DataTable<T>({
  className,
  data,
  columns,
  getRowId = defaultRowId,
  look = "soft",
  density = "comfortable",
  stickyHeader = true,
  loading = false,
  empty,
  emptyTitle = "No results",
  emptyDescription = "Nothing to show yet.",
  selectionMode = "none",
  selectedIds: selectedIdsProp,
  defaultSelectedIds,
  onSelectionChange,
  sort: sortProp,
  defaultSort = null,
  onSortChange,
  clientSort = true,
  loadingRowCount = 5,
  "aria-label": ariaLabel = "Data table",
  ...props
}: DataTableProps<T>) {
  const selectable = selectionMode !== "none";
  const multi = selectionMode === "multiple";

  const sortControlled = sortProp !== undefined;
  const [sortUncontrolled, setSortUncontrolled] =
    useState<DataTableSortState>(defaultSort);
  const sort = sortControlled ? sortProp : sortUncontrolled;

  const selectionControlled = selectedIdsProp !== undefined;
  const [selectedUncontrolled, setSelectedUncontrolled] = useState<string[]>(
    () => defaultSelectedIds ?? [],
  );
  const selectedIds = selectionControlled
    ? selectedIdsProp
    : selectedUncontrolled;
  const selectedSet = useMemo(() => new Set(selectedIds), [selectedIds]);

  const setSelected = useCallback(
    (next: string[]) => {
      if (!selectionControlled) setSelectedUncontrolled(next);
      onSelectionChange?.(next);
    },
    [onSelectionChange, selectionControlled],
  );

  const setSort = useCallback(
    (next: DataTableSortState) => {
      if (!sortControlled) setSortUncontrolled(next);
      onSortChange?.(next);
    },
    [onSortChange, sortControlled],
  );

  const toggleSort = useCallback(
    (columnId: string) => {
      if (!sort || sort.columnId !== columnId) {
        setSort({ columnId, direction: "asc" });
        return;
      }
      if (sort.direction === "asc") {
        setSort({ columnId, direction: "desc" });
        return;
      }
      setSort(null);
    },
    [setSort, sort],
  );

  const sortedData = useMemo(() => {
    if (!clientSort || !sort) return data;
    const column = columns.find((c) => c.id === sort.columnId);
    if (!column?.sortable) return data;

    const indexed = data.map((row, index) => ({ row, index }));
    indexed.sort((a, b) => {
      const av = column.sortValue
        ? column.sortValue(a.row)
        : column.accessor
          ? ((a.row as Record<string, unknown>)[
              column.accessor
            ] as string | number | boolean | null | undefined)
          : undefined;
      const bv = column.sortValue
        ? column.sortValue(b.row)
        : column.accessor
          ? ((b.row as Record<string, unknown>)[
              column.accessor
            ] as string | number | boolean | null | undefined)
          : undefined;
      const cmp = compareSortValues(av, bv);
      return sort.direction === "asc" ? cmp : -cmp;
    });
    return indexed.map((x) => x.row);
  }, [clientSort, columns, data, sort]);

  const rowIds = useMemo(
    () => sortedData.map((row, index) => getRowId(row, index)),
    [getRowId, sortedData],
  );

  const allSelected =
    multi && rowIds.length > 0 && rowIds.every((id) => selectedSet.has(id));

  const toggleAll = useCallback(() => {
    if (!multi) return;
    if (allSelected) setSelected([]);
    else setSelected([...rowIds]);
  }, [allSelected, multi, rowIds, setSelected]);

  const toggleRow = useCallback(
    (id: string) => {
      if (!selectable) return;
      if (multi) {
        if (selectedSet.has(id)) {
          setSelected(selectedIds.filter((x) => x !== id));
        } else {
          setSelected([...selectedIds, id]);
        }
        return;
      }
      // single
      if (selectedSet.has(id)) setSelected([]);
      else setSelected([id]);
    },
    [multi, selectable, selectedIds, selectedSet, setSelected],
  );

  const colSpan = columns.length + (selectable ? 1 : 0);
  const showEmpty = !loading && data.length === 0;

  return (
    <div
      className={cn("sg-data-table", className)}
      data-look={look}
      data-density={density === "comfortable" ? undefined : density}
      data-sticky-header={stickyHeader ? undefined : "false"}
      data-loading={loading || undefined}
      data-empty={showEmpty || undefined}
      data-selection={selectable ? selectionMode : undefined}
      {...props}
    >
      <div className="sg-data-table-scroll">
        <Table aria-label={ariaLabel} aria-busy={loading || undefined}>
          <TableHeader>
            <TableRow>
              {selectable ? (
                <TableHead className="sg-table-head-select" scope="col">
                  {multi ? (
                    <Checkbox
                      aria-label="Select all rows"
                      checked={allSelected}
                      onCheckedChange={() => toggleAll()}
                    />
                  ) : (
                    <span className="sg-table-select-spacer" aria-hidden="true" />
                  )}
                </TableHead>
              ) : null}
              {columns.map((column) => {
                const isSorted =
                  sort?.columnId === column.id ? sort.direction : false;
                return (
                  <TableHead
                    key={column.id}
                    scope="col"
                    align={column.align}
                    sortable={column.sortable}
                    sorted={isSorted}
                    style={columnWidthStyle(column.width)}
                  >
                    {column.sortable ? (
                      <button
                        type="button"
                        className="sg-table-sort-btn"
                        onClick={() => toggleSort(column.id)}
                      >
                        <span className="sg-table-head-label">
                          {column.header}
                        </span>
                        <SortGlyph direction={isSorted} />
                      </button>
                    ) : (
                      <span className="sg-table-head-label">{column.header}</span>
                    )}
                  </TableHead>
                );
              })}
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading
              ? Array.from({ length: Math.max(1, loadingRowCount) }, (_, i) => (
                  <TableRow key={`sk-${i}`} className="sg-table-row-skeleton">
                    {selectable ? (
                      <TableCell className="sg-table-cell-select">
                        <span className="sg-table-skeleton-block" />
                      </TableCell>
                    ) : null}
                    {columns.map((column) => (
                      <TableCell key={column.id} align={column.align}>
                        <span className="sg-table-skeleton-block" />
                      </TableCell>
                    ))}
                  </TableRow>
                ))
              : null}

            {showEmpty ? (
              <TableRow className="sg-table-row-empty">
                <TableCell colSpan={colSpan} className="sg-table-cell-empty">
                  {empty ?? (
                    <EmptyState
                      look="soft"
                      size="sm"
                      title={emptyTitle as string}
                      description={
                        emptyDescription == null
                          ? undefined
                          : (emptyDescription as string)
                      }
                    />
                  )}
                </TableCell>
              </TableRow>
            ) : null}

            {!loading && !showEmpty
              ? sortedData.map((row, index) => {
                  const id = getRowId(row, index);
                  const isSelected = selectedSet.has(id);
                  return (
                    <TableRow key={id} selected={isSelected}>
                      {selectable ? (
                        <TableCell className="sg-table-cell-select">
                          <Checkbox
                            aria-label={`Select row ${id}`}
                            checked={isSelected}
                            onCheckedChange={() => toggleRow(id)}
                          />
                        </TableCell>
                      ) : null}
                      {columns.map((column) => (
                        <TableCell
                          key={column.id}
                          align={column.align}
                          style={columnWidthStyle(column.width)}
                        >
                          {cellContent(column, row, index)}
                        </TableCell>
                      ))}
                    </TableRow>
                  );
                })
              : null}
          </TableBody>
        </Table>
      </div>
    </div>
  );
}

/** Values allowed in `cn(...)` — only strings survive. */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type ClassValue = string | false | null | undefined | 0 | 0n | boolean;

/**
 * Tiny class merger — no runtime deps.
 * Prefer this over pulling tailwind-merge until we need conflict resolution.
 */
export function cn(...parts: ClassValue[]): string {
  return parts.filter((part): part is string => typeof part === "string" && part.length > 0).join(" ");
}

/** Shared visual “look” languages across controls. */

export type ButtonLook = "solid" | "soft" | "glass" | "gradient" | "neon";

export type RadioLook = "dot" | "card" | "chip";

export type CheckboxLook = "box" | "card" | "pill";

export type SwitchLook = "track" | "ios" | "minimal";

export type BadgeLook = "soft" | "solid" | "outline" | "glow";

export type FieldLook = "solid" | "underline" | "filled" | "ghost";

export type SelectLook = "solid" | "soft" | "glass" | "gradient";

export type TabsLook = "pill" | "underline" | "segmented";

export type AvatarLook = "circle" | "rounded" | "soft";

export type TooltipLook = "frost" | "solid" | "accent";

export type CardLook = "flat" | "raised" | "outline" | "glow";

/** NumberInput shell + stepper language */
export type NumberInputLook = "soft" | "solid" | "outline" | "ghost";

/** Slider track / thumb language */
export type SliderLook = "soft" | "solid" | "glass" | "accent";

/** FileField trigger surface */
export type FileFieldLook = "solid" | "soft" | "dashed" | "ghost";

/** Progress track / fill language */
export type ProgressLook = "soft" | "solid" | "glass" | "accent" | "striped";

/** StatusDot chrome language (color still from status / color) */
export type StatusDotLook = "soft" | "solid" | "outline" | "glow";

/** Chip surface language */
export type ChipLook = "soft" | "solid" | "outline" | "glass" | "glow";

/** CloseButton chrome */
export type CloseButtonLook = "ghost" | "soft" | "solid" | "danger";

/**
 * Collapsible / Accordion disclosure surface
 * soft = frost card · solid = long content · glass = chrome · outline = border only · ghost = flush list
 */
export type CollapsibleLook = "soft" | "solid" | "glass" | "outline" | "ghost";

export type AccordionLook = CollapsibleLook;

/** Breadcrumb chrome: plain path · soft tray · pill chips */
export type BreadcrumbLook = "plain" | "soft" | "pill";

/** Pagination control chrome */
export type PaginationLook = "soft" | "solid" | "ghost" | "glass";

/** EmptyState surface */
export type EmptyStateLook = "solid" | "soft" | "outline";

/**
 * Stepper language
 * soft = frost track · solid = solid rail · outline = line only
 * dots = progress line + large dots · pills = segmented chip row
 */
export type StepperLook = "soft" | "solid" | "outline" | "dots" | "pills";

/**
 * Toolbar strip
 * soft | solid | glass | ghost | accent (accent edge rail)
 */
export type ToolbarLook = "soft" | "solid" | "glass" | "ghost" | "accent";

/** List host surface */
export type ListLook = "soft" | "solid" | "outline" | "ghost" | "inset";

/**
 * Stat metric tile
 * solid | soft | glass | outline | accent (left rail)
 */
export type StatLook = "solid" | "soft" | "glass" | "outline" | "accent";

/** PageHeader chrome: plain flush · soft frost · solid panel · glass chrome */
export type PageHeaderLook = "plain" | "soft" | "solid" | "glass";

/** SettingsSection panel chrome */
export type SettingsSectionLook = "soft" | "solid" | "glass" | "plain";

/**
 * DataTable surface language
 * soft = frost · solid = panel · glass = chrome · outline = border · ghost = flush
 */
export type DataTableLook = "soft" | "solid" | "glass" | "outline" | "ghost";

/**
 * Motion recipes — component-specific animation menus.
 * Parallel to `look` (visual surface). Always pair with `prefers-reduced-motion`.
 *
 * Defaults match the pre-motion global micro-interactions so existing UIs
 * keep the same feel when no prop is passed.
 */

/** Shared “off” token used on every control. */
export type MotionNone = "none";

export type ButtonMotion = MotionNone | "lift" | "press" | "sheen" | "ripple";

export type CheckboxMotion = MotionNone | "pop" | "draw" | "fade-in" | "bounce";

export type RadioMotion = MotionNone | "pop" | "dot-scale" | "ring-expand";

export type SwitchMotion = MotionNone | "snap" | "spring" | "elastic";

export type FieldMotion = MotionNone | "ring" | "underline-grow" | "glow";

export type SelectMotion = MotionNone | "fade" | "scale" | "slide-down";

export type TooltipMotion = MotionNone | "fade" | "scale" | "slide";

export type BadgeMotion = MotionNone | "pulse" | "pop-in" | "shimmer";

export type AvatarMotion = MotionNone | "lift" | "ring-pulse" | "status-ping";

/**
 * Tabs indicator + content enter.
 * - none: instant active swap
 * - fade: soft cross-fade on active chrome / content
 * - slide: moving pill or underline indicator (content still fades)
 */
export type TabsMotion = MotionNone | "fade" | "slide";

export type ModalMotion = MotionNone | "scale" | "fade" | "slide-up";

export type ToastMotion = MotionNone | "slide-in" | "pop";

export type CardMotion = MotionNone | "lift" | "glow-pulse";

/** Popover / DropdownMenu panel enter (same recipe set as Select menu). */
export type PopoverMotion = MotionNone | "fade" | "scale" | "slide-down";

export type DropdownMenuMotion = MotionNone | "fade" | "scale" | "slide-down";

/** ContextMenu panel — same recipes as DropdownMenu / Popover. */
export type ContextMenuMotion = MotionNone | "fade" | "scale" | "slide-down";

/** DatePicker calendar panel — same recipes as Select. */
export type DatePickerMotion = MotionNone | "fade" | "scale" | "slide-down";

/** Collapsible / Accordion panel open motion. */
export type CollapsibleMotion = MotionNone | "fade" | "height";

export type AccordionMotion = CollapsibleMotion;

/** Sheet edge panel enter/exit. */
export type SheetMotion = MotionNone | "slide" | "fade";

/** HoverCard panel (Popover family). */
export type HoverCardMotion = MotionNone | "fade" | "scale" | "slide-down";

/** Defaults — preserve current product feel. */
export const MOTION_DEFAULTS = {
  button: "lift",
  checkbox: "pop",
  radio: "pop",
  switch: "spring",
  field: "ring",
  select: "scale",
  tooltip: "scale",
  badge: "none",
  avatar: "lift",
  tabs: "slide",
  modal: "scale",
  toast: "slide-in",
  card: "lift",
  popover: "scale",
  dropdownMenu: "scale",
  contextMenu: "scale",
  datePicker: "scale",
  collapsible: "height",
  accordion: "height",
  sheet: "slide",
  hoverCard: "scale",
} as const satisfies Record<string, string>;
